# Verify IoI section I claim: remove g<=min(q,4f+2) coupling -> 976 becomes 1,000; 24 excluded all f=0,g=3
L = []
for n in (1,2,3):
    for l in range(0, min(n-1,1)+1):
        for k in range(1, min(4*l+2,3)+1):
            for q in range(0, k+1):
                for e in (1,2,3):
                    for f in range(0, min(e-1,1)+1):
                        for g in range(0, min(4*f+2,q)+1):
                            for S2 in range(0, k+1):
                                L.append((n,l,k,q,e,f,g,S2))
base = set(L)
# uncoupled: g bounded only by... "Remove it" = remove the g<=min(q,4f+2) term entirely; g ranges over the alphabet 0..3
alphg = sorted(set(c[6] for c in base))
U = []
for n in (1,2,3):
    for l in range(0, min(n-1,1)+1):
        for k in range(1, min(4*l+2,3)+1):
            for q in range(0, k+1):
                for e in (1,2,3):
                    for f in range(0, min(e-1,1)+1):
                        for g in alphg:
                            for S2 in range(0, k+1):
                                U.append((n,l,k,q,e,f,g,S2))
U = set(U)
print("with coupling:", len(base), "| without:", len(U))
exc = U - base
print("excluded:", len(exc), "| all f=0,g=3:", all(c[5]==0 and c[6]==3 for c in exc))
